// <auto-generated/>
namespace Sunplus.Agent.Model.Services
{
    using System.Collections;
    using System.Web;
    using Sunplus.Core.Common.IPs;
    using Sunplus.Core.Common.IPs.DAL;

    public class DeviceService
    {
        public static Hashtable GetRequestInfo(HttpRequest request)
        {
            // Get Browser
            Hashtable requestInfo = new Hashtable();

            requestInfo.Add("loginip", string.Empty);
            requestInfo.Add("countrycode", string.Empty);
            requestInfo.Add("logindomain", string.Empty);

            requestInfo.Add("browsername", string.Empty);
            requestInfo.Add("platform", string.Empty);

            string ip = Sunplus.Agent.Model.Common.AgentIPFormat.GetClientIP();
            string country = "Unknown";

            requestInfo["loginip"] = ip;
            requestInfo["countrycode"] = country;
            requestInfo["logindomain"] = request.ServerVariables["SERVER_NAME"];

            try
            {
                IPTable infoIp = IpUtils.LocationFromIP(ip);
                country = (infoIp.CountryLong == "Reserved") ? null : infoIp.CountryLong;

                requestInfo["loginip"] = ip;
                requestInfo["countrycode"] = country;
            }
            catch
            {
            }

            try
            {
                // Mobile Device Browser
                if (request.Browser.IsMobileDevice)
                {
                    requestInfo["browsername"] = request.Browser.Browser + " " + request.Browser.MajorVersion;
                    requestInfo["platform"] = request.Browser.MobileDeviceModel;
                }
                else
                {
                    requestInfo["browsername"] = (request.UserAgent.ToLower().Contains("chrome") ? "Chrome" : request.Browser.Browser) + " " + request.Browser.Version;
                    requestInfo["platform"] = GetPlatform();
                }
            }
            catch
            {
            }

            return requestInfo;
        }

        private static string GetPlatform()
        {
            // Create a list of all platform
            string[] platform = new[] { "Windows 3", "Win16", "Windows 95", "Win95", "Windows 98", "Win98", "Windows 2000", "Windows XP", "Windows Server 2003", "Windows Vista", "Windows NT", "WinNT", "Windows ME", "Open BSD", "OpenBSD", "Sun OS", "SunOS", "Linux", "Mac OS", "Mac_PowerPC", "Macintosh", "QNX", "QNX", "BeOS", "BeOS", "OS/2", "OS/2" };
            HttpContext context = HttpContext.Current;

            // Loop through each item in the list created above and check if the header contains that text
            foreach (string s in platform)
            {
                if (context.Request.ServerVariables["HTTP_USER_AGENT"].ToLower().Contains(s.ToLower()))
                {
                    return s;
                }
            }

            return "Unknown";
        }
    }
}